import{_ as o,C as s,o as i,c as r,ah as t,E as a}from"./chunks/framework.sPHStHqt.js";const b=JSON.parse('{"title":"Tenant Management","description":"","frontmatter":{},"headers":[],"relativePath":"super-admin/tenant-management.md","filePath":"super-admin/tenant-management.md","lastUpdated":1789630599000}'),l={name:"super-admin/tenant-management.md"};function d(c,e,m,h,g,u){const n=s("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="tenant-management" tabindex="-1">Tenant Management <a class="header-anchor" href="#tenant-management" aria-label="Permalink to &quot;Tenant Management&quot;">​</a></h1><p>Every business on your platform is a <strong>tenant</strong> — a company with its own CRM on its own subdomain. This is where you see them all, add one by hand, edit their details, or switch one off.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to read the tenant list</li><li>How to create a tenant yourself</li><li>How to block a tenant, and what blocking does</li><li>How to remove a tenant for good</li></ul></div><h2 id="the-tenant-list" tabindex="-1">The tenant list <a class="header-anchor" href="#the-tenant-list" aria-label="Permalink to &quot;The tenant list&quot;">​</a></h2><p>Open <strong>Tenants</strong> in the sidebar. Every tenant is listed, newest first.</p>',5)),a(n,{src:"/images/tenants/tenant-grid.png",alt:"Tenant list"}),e[1]||(e[1]=t('<p>Each row shows:</p><ul><li><strong>ID</strong> — the tenant&#39;s internal number.</li><li><strong>Name</strong> — the business name.</li><li><strong>Email</strong> — the address the account was opened with.</li><li><strong>Username</strong> — the subdomain label, so <code>site1</code> means <code>site1.yourplatform.com</code>.</li><li><strong>Domain</strong> — the full CRM address.</li><li><strong>CName</strong> — a custom domain, if the tenant has pointed one at the platform. Blank otherwise. See <a href="/tenants/custom-domains">Custom Domains</a>.</li><li><strong>Status</strong> — <strong>Active</strong> or <strong>Inactive</strong>.</li></ul><p>Use <strong>Search</strong> to find a tenant by name or email, <strong>Filter</strong> to narrow by status, and <strong>Per Page</strong> to show more rows at once.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most tenants create themselves by signing up — see <a href="/tenants/registration">Registration</a>. You usually only come here to <em>manage</em> the ones that already exist.</p></div><h2 id="creating-a-tenant" tabindex="-1">Creating a tenant <a class="header-anchor" href="#creating-a-tenant" aria-label="Permalink to &quot;Creating a tenant&quot;">​</a></h2><p>Select <strong>Create Tenant</strong> to open a tenant on someone&#39;s behalf — useful when you&#39;re setting an account up for a customer directly.</p>',6)),a(n,{src:"/images/tenants/tenant-create.png",alt:"Create Tenant form"}),e[2]||(e[2]=t('<ul><li><strong>Email</strong> <em>(required)</em> — the tenant admin&#39;s sign-in address. Must be unique.</li><li><strong>Password</strong> <em>(required)</em> — at least 6 characters, with one number and one special character.</li><li><strong>User Name</strong> <em>(required)</em> — becomes the subdomain, so <code>acme</code> gives <code>acme.yourplatform.com</code>. Lowercase letters, numbers and single hyphens only.</li><li><strong>CName</strong> <em>(optional)</em> — a custom domain to serve the CRM from, entered as a bare hostname like <code>crm.example.com</code> — no <code>http://</code>, no trailing path. Each domain can belong to only one tenant.</li><li><strong>Name</strong> — the business name (optional; can be added later).</li><li><strong>Description</strong> — a note for your own reference (optional).</li><li><strong>Status</strong> — leave off to create the tenant blocked, or turn it on to let them sign in straight away.</li></ul><p>Select <strong>Save as Tenant</strong>. Their CRM is provisioned immediately — pipelines, roles and starter data are all set up, exactly as if they had registered themselves.</p><h2 id="editing-a-tenant" tabindex="-1">Editing a tenant <a class="header-anchor" href="#editing-a-tenant" aria-label="Permalink to &quot;Editing a tenant&quot;">​</a></h2><p>The pencil icon on a row opens the same form pre-filled. You can change the name, email, custom domain and status. The <strong>Password</strong> field is optional here — leave it blank to keep the current one, or enter a new one to reset it.</p><h2 id="blocking-a-tenant" tabindex="-1">Blocking a tenant <a class="header-anchor" href="#blocking-a-tenant" aria-label="Permalink to &quot;Blocking a tenant&quot;">​</a></h2><p>Turning a tenant&#39;s <strong>Status</strong> off — on the edit form, or by selecting rows and using the bulk status action — <strong>blocks</strong> them.</p><p>A blocked tenant:</p><ul><li>can no longer sign in, on either their subdomain or their custom domain;</li><li>keeps all their data untouched;</li><li>still appears in this list, and in the <strong>Blocked Tenants</strong> figure on the <a href="/super-admin/dashboard">dashboard</a>.</li></ul><p>Turn Status back on to restore access. Nothing is lost in between.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Blocking is the reversible way to suspend an account — for non-payment, say. Reach for it before you reach for delete.</p></div><h2 id="deleting-a-tenant" tabindex="-1">Deleting a tenant <a class="header-anchor" href="#deleting-a-tenant" aria-label="Permalink to &quot;Deleting a tenant&quot;">​</a></h2><p>The trash icon removes a tenant.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Deleting a tenant is permanent. Their CRM, and every lead, contact and quote inside it, is gone and cannot be recovered. To suspend an account temporarily, <strong>block</strong> it instead.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>See what a tenant&#39;s leads and quotes look like from your side → <a href="/super-admin/leads">Leads</a> · <a href="/super-admin/quotes">Quotes</a></li><li>Understand what a tenant gets on sign-up → <a href="/tenants/tenant-workspace">The Tenant Workspace</a></li><li>Set a tenant up with their own domain → <a href="/tenants/custom-domains">Custom Domains</a></li></ul>',15))])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
